  > -->
  <v-scale-screen
    :width="screenSize.width"
    :height="screenSize.height"
    :style="screenStyle"
    :delay="80"
    :wrapper-style="{ transitionDuration: '0ms' }"
    style="margin-bottom: 10px"
    :fullScreen="false"
  >
    <div class="header-top">
      <div class="top-time">{{ NowTime }}</div>
      <div class="header">
        <div class="selectRange">
          <Menu
            mode="horizontal"
            ref="menus"
