            :active-name="$route.name"
          >
            <MenuItem class="menu-item" name="operationAtatus">
              运行状况
            </MenuItem>
            <MenuItem name="productionInformation"> 生产信息 </MenuItem>

            <MenuItem name="productAnalysis"> 生产分析 </MenuItem>
          </Menu>
        </div>
