<script>
import { parseTime } from "@/utils";

export default {
  name: "home",
  data() {
    return {
      NowTime: "",
      screenSize: {
        width: 1920,
        height: 1080,
      },
    };
  },
  computed: {
    isPortraitLayout() {
      return this.screenSize.width === 1024;
    },
    screenStyle() {
      const headerHeight = this.isPortraitLayout ? 150 : 90;
      return {
        "--screen-height": `${this.screenSize.height}px`,
        "--page-height": `${this.screenSize.height - headerHeight}px`,
      };
    },
  },
  mounted() {
    this.getTime();
    this.updateScreenSize();
    window.addEventListener("resize", this.updateScreenSize);
    window.addEventListener("orientationchange", this.updateScreenSize);
  },
  beforeDestroy() {
    window.removeEventListener("resize", this.updateScreenSize);
    window.removeEventListener("orientationchange", this.updateScreenSize);
  },
  methods: {
    updateScreenSize() {
      const width = window.innerWidth;
      const height = window.innerHeight;
      let size;

      if (height > width && width <= 1100) {
        size = { width: 1024, height: 1366 };
      } else if (width >= 1680) {
        size = { width: 1920, height: 1080 };
      } else {
        size = { width: 1366, height: 768 };
      }

      if (
        size.width !== this.screenSize.width ||
        size.height !== this.screenSize.height
      ) {
        this.screenSize = size;
      }
    },
    getTime() {
      this.NowTime = parseTime(new Date());
      setTimeout(() => {
        this.getTime();
      }, 1000);
    },
  },
};
</script>

